/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountXrayCodeLens, type XrayCodeLensOptions } from "../../components/xray-code-lens/XrayCodeLensEngine.js";
import type { MotionController } from "../../components/xray-code-lens/motion-runtime";

export function XrayCodeLens(props: { options?: XrayCodeLensOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountXrayCodeLens(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="xray-code-lens" />;
}

